const std = @import("std");

fn search(text: []const u8, pattern: []const u8) void {
    const d: u64 = 256;
    const q: u64 = 101;
    const m = pattern.len;
    const n = text.len;
    var p: u64 = 0;
    var t: u64 = 0;
    var h: u64 = 1;

    for (0..m - 1) |_| h = (h * d) % q;
    for (0..m) |i| {
        p = (d * p + pattern[i]) % q;
        t = (d * t + text[i]) % q;
    }

    for (0..n - m + 1) |i| {
        if (p == t) {
            var match = true;
            for (0..m) |j| {
                if (text[i + j] != pattern[j]) { match = false; break; }
            }
            if (match) std.debug.print("Found at {}\n", .{i});
        }
        if (i < n - m) {
            t = (d * (t - text[i] * h) + text[i + m]) % q;
            t +%= q;
        }
    }
}

pub fn main() !void {
    const text = "ABCCDDAEFG";
    const pattern = "CDD";
    search(text, pattern);
}

